    ui_menu_item 6 "Docker+UFW audit" "check the firewall bypass"
    ui_menu_item 7 "Support report" "full plain-text dump for issues/tickets"
    ui_menu_item 8 "XanMod kernel (BBRv3)" "ADVANCED — replaces the kernel"
    ui_menu_item 9 "Bandwidth test" "speedtest client or plain HTTP download"
    ui_menu_item b "Quick benchmark" "CPU and disk, no dependencies"
    ui_menu_item w "Live view" "conntrack, sockets and traffic under load"
    ui_menu_item m "APT mirror" "switch to an Iranian mirror (or revert)"
    ui_menu_item 0 "Back"
    ui_hr
    read -rp "Select: " choice || return 0
    case "${choice:-}" in
      1)
        tools_ping_matrix
        ui_pause
        ;;
      2)
        dns_latency_test
        ui_pause
        ;;
      3)
        tools_tcp_status
        ui_pause
        ;;
      4)
        tools_listening_ports
        ui_pause
        ;;
      5)
        vpn_mss_clamp
        ui_pause
        ;;
      n | N)
        vpn_conntrack_bypass
        ui_pause
        ;;
      6)
        vpn_docker_ufw_audit
        ui_pause
        ;;
      7)
        tools_report
        ui_pause
        ;;
      8)
        kernel_xanmod_install
        ui_pause
        ;;
      9)
        tools_speedtest || true # outcome already reported
        ui_pause
        ;;
      b | B)
        tools_benchmark
        ui_pause
        ;;
      w | W) tools_watch || true ;;
      m | M)
        mirror_apply || true
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/modules/selfupdate.sh -------------------------
# ============================================================================
# modules/selfupdate.sh — install as the `st` command and self-update.
#
# Downloads prefer the latest GitHub Release (with SHA-256 verification when
# sha256sum is available) and fall back to the raw main build only while no
# release exists yet. Every downloaded file must pass `bash -n` and a
# fingerprint check before it replaces anything.
# ============================================================================

readonly ST_INSTALL_PATH='/usr/local/bin/st'
readonly ST_URL_RELEASE='https://github.com/Sir-Adnan/server-tools/releases/latest/download/server-tools.sh'
readonly ST_URL_RELEASE_SUMS='https://github.com/Sir-Adnan/server-tools/releases/latest/download/SHA256SUMS'
readonly ST_URL_RAW='https://raw.githubusercontent.com/Sir-Adnan/server-tools/main/dist/server-tools.sh'

# _self_source_path — path of the running script, empty when running from a
# pipe/process substitution (`bash <(curl ...)` yields a non-reusable /dev/fd).
_self_source_path() {
  local src="${BASH_SOURCE[0]:-}"
  if [[ -f $src && -r $src ]]; then
    printf '%s' "$src"
    return 0
  fi
  return 1
}

# _self_download DEST — fetch, verify (checksum + parse + fingerprint), move.
_self_download() {
  local dest="$1" tmp="${ST_LIB_DIR}/download.$$" from_release=0
  if ! has_cmd curl; then
    log_error "curl is required to download ServerTools."
    return 1
  fi

  if curl -fsSL --max-time 60 "$ST_URL_RELEASE" -o "$tmp" 2>>"$ST_LOG_FILE"; then
    from_release=1
  elif ! curl -fsSL --max-time 60 "$ST_URL_RAW" -o "$tmp" 2>>"$ST_LOG_FILE"; then
    rm -f "$tmp"
    log_error "Download failed (release and raw fallback) — see the log."
    return 1
  fi

  if ((from_release)) && has_cmd sha256sum; then
    local sums expected actual
    sums="$(curl -fsSL --max-time 30 "$ST_URL_RELEASE_SUMS" 2>>"$ST_LOG_FILE")" || sums=''
    if [[ -z $sums ]]; then
      log_warn "SHA256SUMS could not be fetched — the release was NOT checksum-verified."
      printf '%sWarning:%s checksum file unavailable; only syntax checks were run.\n' "$C_WARN" "$C_RESET"
    fi
    if [[ -n $sums ]]; then
      expected="$(awk '/server-tools\.sh/ {print $1; exit}' <<<"$sums")"
      actual="$(sha256sum "$tmp" | awk '{print $1}')"
      if [[ -n $expected && $expected != "$actual" ]]; then
        rm -f "$tmp"
        log_error "SHA-256 mismatch on the downloaded release — aborting."
        return 1
      fi
    fi
  fi

  if ! bash -n "$tmp" 2>>"$ST_LOG_FILE" || ! grep -q 'ST_NAME="ServerTools"' "$tmp"; then
    rm -f "$tmp"
    log_error "Downloaded file failed sanity checks — nothing was replaced."
    return 1
  fi
  mv -f "$tmp" "$dest"
}

st_self_install() {
  local src
  mkdir -p "$(dirname "$ST_INSTALL_PATH")"
  # Deliberately NOT tracked: the installed command is the tool itself, not a
  # system change — a later rollback must never delete the user's `st`.
  if src="$(_self_source_path)"; then
    cp -f "$src" "$ST_INSTALL_PATH"
  else
    printf 'Running from a pipe — downloading the current build instead.\n'
    _self_download "$ST_INSTALL_PATH" || return 1
  fi
  chmod 755 "$ST_INSTALL_PATH"
  printf '%sInstalled.%s Run %sst%s from now on; update anytime with: st --update\n' \
    "$C_OK" "$C_RESET" "$C_KEY" "$C_RESET"
  log_info "Installed to ${ST_INSTALL_PATH} (v${ST_VERSION})."
}

st_self_update() {
  local target new_ver staged="${ST_LIB_DIR}/update.$$"
  if [[ -f $ST_INSTALL_PATH ]]; then
    target="$ST_INSTALL_PATH"
  elif ! target="$(_self_source_path)"; then
    log_error "Not installed and not running from a file — use --install first."
    return 1
  fi

  # Single download: fetch once through the verifying path into a staging
  # file, read its version, and promote that exact verified file.
  _self_download "$staged" || return 1

  new_ver="$(grep -oE 'ST_VERSION="[^"]+"' "$staged" | head -n1 | cut -d'"' -f2)" || new_ver=''
  if [[ -z $new_ver ]]; then
    rm -f "$staged"
    log_error "Could not read the downloaded version — aborting."
    return 1
  fi
  if [[ $new_ver == "$ST_VERSION" ]]; then
    printf 'Already up to date (v%s).\n' "$ST_VERSION"
    rm -f "$staged"
    return 0
  fi

  mv -f "$staged" "$target"
  chmod 755 "$target"
  printf '%sUpdated:%s v%s -> v%s (%s)\n' "$C_OK" "$C_RESET" "$ST_VERSION" "$new_ver" "$target"
  log_info "Self-updated: v${ST_VERSION} -> v${new_ver}."
}

# ------------------------- src/modules/optimize.sh -------------------------
# ============================================================================
# modules/optimize.sh — Quick/Custom Optimize flows:
# plan → confirm → apply steps with honest per-step outcomes → summary.
#
# NOTE: step functions run via `"$fn" || rc=$?`, which suppresses errexit for
# their whole body (bash semantics). Steps therefore signal outcomes with
# explicit return codes: 0=ok, 1=failed, 2=skipped, 3=applied with warnings.
# ============================================================================

ST_STEP_RESULTS=()
ST_STEP_IDX=0
ST_STEP_TOTAL=0

# --auto flags, filled by the CLI parser in 99-main.sh.
ST_AUTO_PROFILE=''
ST_AUTO_TIER=''
ST_AUTO_USERS=''
ST_AUTO_DNS=''
ST_AUTO_SWAP=1
ST_AUTO_LIMITS=1
ST_AUTO_EXTRAS=1
ST_AUTO_PERF=1

st_run_step() { # st_run_step TITLE FN
  local title="$1" fn="$2" rc=0 note
  ST_STEP_IDX=$((ST_STEP_IDX + 1))
  printf '%s[%d/%d]%s %s ... ' "$C_KEY" "$ST_STEP_IDX" "$ST_STEP_TOTAL" "$C_RESET" "$title"

  # Keep the status line intact: warnings are collected and printed below it.
  ST_LOG_BUFFER=()
  ST_LOG_BUFFERING=1
  "$fn" || rc=$?
  ST_LOG_BUFFERING=0
  case "$rc" in
    0)
      printf '%sOK%s\n' "$C_OK" "$C_RESET"
      ST_STEP_RESULTS+=("ok|${title}")
      ;;
    2)
      printf '%sSKIPPED%s\n' "$C_MUTED" "$C_RESET"
      ST_STEP_RESULTS+=("skip|${title}")
      ;;
    3)
      printf '%sWARN%s\n' "$C_WARN" "$C_RESET"
      ST_STEP_RESULTS+=("warn|${title}")
      st_escalate_exit 3
      ;;
    *)
      printf '%sFAILED%s\n' "$C_ERR" "$C_RESET"
      ST_STEP_RESULTS+=("fail|${title}")
      st_escalate_exit 1
      ;;
  esac

  for note in "${ST_LOG_BUFFER[@]-}"; do
    [[ -n $note ]] && printf '      %s%s%s\n' "$C_MUTED" "$note" "$C_RESET"
  done
  ST_LOG_BUFFER=()
  return 0
}

# --- Before/after snapshot -------------------------------------------------
# Kernel counters captured before the first change, so the effect of the
# tuning can be shown later instead of merely claimed.

readonly ST_SNAPSHOT_FILE="${ST_LIB_DIR}/snapshot.tsv"

_snapshot_counters() {
  local retrans='0' insegs='0' outsegs='0' drops='0' ct='0'
  if [[ -r /proc/net/snmp ]]; then
    # The Tcp: header line names the columns; the next Tcp: line holds values.
    # IFS is forced to a space for this read: the global IFS ($'\n\t') has no
    # space, so awk's space-separated output would otherwise land entirely in
    # $retrans and break the arithmetic in snapshot_report. A missing snmp
    # table (some containers) just leaves the defaults above.
    IFS=' ' read -r retrans insegs outsegs < <(awk '
      /^Tcp:/ { if (!h) { for (i = 1; i <= NF; i++) idx[$i] = i; h = 1; next }
                print $idx["RetransSegs"], $idx["InSegs"], $idx["OutSegs"]; exit }' /proc/net/snmp) || true
  fi
  if [[ -r /proc/net/dev ]]; then
    drops="$(awk 'NR > 2 {rx += $5; tx += $12} END {print rx + tx + 0}' /proc/net/dev)"
  fi
  ct="$(sysctl_get net.netfilter.nf_conntrack_count)"
  [[ $ct =~ ^[0-9]+$ ]] || ct=0
  printf '%s\t%s\t%s\t%s\t%s' "${retrans:-0}" "${insegs:-0}" "${outsegs:-0}" "${drops:-0}" "$ct"
}

snapshot_save() {
  local now
  now="$(_snapshot_counters)" || return 0
  printf 'taken_at\t%s\n' "$(date '+%F %T')" >"$ST_SNAPSHOT_FILE"
  printf 'counters\t%s\n' "$now" >>"$ST_SNAPSHOT_FILE"
  log_debug "baseline snapshot stored"
}

# snapshot_report — deltas since the baseline; silent when none was taken.
snapshot_report() {
  [[ -f $ST_SNAPSHOT_FILE ]] || return 2
  local taken old new
  taken="$(awk -F'\t' '$1 == "taken_at" {print $2; exit}' "$ST_SNAPSHOT_FILE")"
  old="$(awk -F'\t' '$1 == "counters" {print $2 "\t" $3 "\t" $4 "\t" $5 "\t" $6; exit}' "$ST_SNAPSHOT_FILE")"
  new="$(_snapshot_counters)"

  local o_re o_in o_out o_drop _o_ct n_re n_in n_out n_drop n_ct
  IFS=$'\t' read -r o_re o_in o_out o_drop _o_ct <<<"$old"
  IFS=$'\t' read -r n_re n_in n_out n_drop n_ct <<<"$new"

  local d_re=$((n_re - o_re)) d_seg=$((n_in - o_in + n_out - o_out)) d_drop=$((n_drop - o_drop))
  ui_kv "Baseline taken" "$taken"
  if ((d_seg > 0)); then
    # Retransmit rate in per-mille keeps integer math honest on small samples.
    ui_kv "TCP retransmits" "${d_re} of ${d_seg} segments ($((d_re * 1000 / d_seg))‰ since baseline)"
  else
    ui_kv "TCP retransmits" "${d_re} since baseline"
  fi
  ui_kv "Interface drops" "${d_drop} since baseline"
  ui_kv "Conntrack now" "$n_ct"
  return 0
}

st_report_summary() {
  local entry status _title ok=0 warn=0 fail=0 skip=0
  for entry in "${ST_STEP_RESULTS[@]-}"; do
    [[ -n $entry ]] || continue # empty array expands to one empty element
    IFS='|' read -r status _title <<<"$entry"
    case "$status" in
      ok) ok=$((ok + 1)) ;;
      warn) warn=$((warn + 1)) ;;
      skip) skip=$((skip + 1)) ;;
      fail) fail=$((fail + 1)) ;;
    esac
  done

  ui_hr
  if ((fail > 0)); then
    printf '%sCompleted with failures:%s %d ok, %d warned, %d skipped, %d failed — see the log.\n' \
      "$C_ERR" "$C_RESET" "$ok" "$warn" "$skip" "$fail"
  elif ((warn > 0)); then
    printf '%sCompleted with warnings:%s %d ok, %d warned, %d skipped — details in the log.\n' \
      "$C_WARN" "$C_RESET" "$ok" "$warn" "$skip"
  else
    printf '%sAll steps completed:%s %d applied, %d skipped.\n' "$C_OK" "$C_RESET" "$ok" "$skip"
  fi
  ui_kv "Backups" "$ST_RUN_BACKUP_DIR"
  ui_kv "Log" "$ST_LOG_FILE"
  ui_kv "Rollback" "menu option [4], or: --rollback"
  printf '%sNo daemons or cron jobs were installed — nothing stays running.%s\n' "$C_MUTED" "$C_RESET"
}

_optimize_show_plan() {
  ui_kv "Profile" "${ST_PROFILE} (${ST_PROFILE_SOURCE})"
  if ((ST_EXPECTED_USERS > 0)); then
    ui_kv "Capacity" "${ST_EXPECTED_USERS} expected users (conntrack sized from users; buffers from RAM tier ${ST_TIER})"
  else
    ui_kv "Capacity tier" "${ST_TIER} — up to ${ST_TIER_USERS} concurrent users"
  fi
  if profile_wants_forwarding; then
    ui_kv "Conntrack" "${ST_CONNTRACK} entries (~$(tier_conntrack_ram_mb) MB kernel RAM worst case)"
  fi
  ui_kv "Socket buffers" "up to ${ST_BUF_MB} MB per socket"
  ui_kv "Congestion" "BBR when the kernel supports it, else cubic"

  local warn
  warn="$(capacity_warning)"
  if [[ -n $warn ]]; then
    printf '  %sCapacity warning:%s %s\n' "$C_WARN" "$C_RESET" "$warn"
    log_info "capacity warning: ${warn}"
  fi
}

# _optimize_run WITH_DNS WITH_SWAP WITH_LIMITS WITH_EXTRAS WITH_PERF  (each 0/1)
_optimize_run() {
  local with_dns="$1" with_swap="$2" with_limits="$3" with_extras="$4" with_perf="${5:-0}"
  ST_STEP_RESULTS=()
  ST_STEP_IDX=0
  ST_STEP_TOTAL=$((1 + with_dns + with_swap + with_limits + with_extras + with_perf))
  # Baseline first: counters must be read before anything is changed.
  snapshot_save
  ui_hr
  # Swap runs BEFORE sysctl on purpose: vm.swappiness depends on whether the
  # host ends up on compressed RAM (zram) or a disk swap file.
  ((with_swap)) && st_run_step "Swap" swap_apply
  st_run_step "Kernel network tuning (sysctl, tier ${ST_TIER})" sysctl_apply
  # CPU/NIC data-path tuning (RPS/RFS/XPS, governor, THP) complements sysctl.
  ((with_perf)) && st_run_step "CPU & NIC performance (RPS, governor, THP)" perf_apply
  ((with_limits)) && st_run_step "File-descriptor limits (nofile)" limits_apply
  ((with_extras)) && st_run_step "Journald cap & NTP" extras_apply
  ((with_dns)) && st_run_step "DNS (${ST_DNS1} / ${ST_DNS2})" dns_apply
  st_report_summary
  # Show what actually answers queries — a written config proves nothing.
  ((with_dns)) && ui_kv "DNS in effect" "$(dns_effective_servers)"
  _offer_service_restart
  config_set last_profile "$ST_PROFILE"
  config_set last_tier "$ST_TIER"
  backup_prune 10
  return 0
}

# _offer_service_restart — running services keep their old nofile limit
# until restarted; offer to restart detected VPN workloads (interactive),
# or just say so honestly (batch).
_offer_service_restart() {
  ((ST_LIMITS_CHANGED)) || return 0

  # Match on name AND image: a pg-node container is often just called "node"
  # while only its image identifies it (same source as detect_stack).
  # grep exit 1 (no match) is a normal outcome here, not an error.
  local containers='' engine
  for engine in docker podman; do
    has_cmd "$engine" || continue
    containers+="$("$engine" ps --format '{{.Names}} {{.Image}}' 2>/dev/null |
      grep -iE 'marzban|marznode|pg[-_]?node|pasarguard|gozargah|x-?ui|xray|hiddify|sing-?box|hysteria|wireguard|wg-' |
      awk -v e="$engine" '{print e "\t" $1}' || true)"
  done

  if [[ -n $containers ]]; then
    printf '%sNote:%s containers inherit their file limit from the container engine,\n' "$C_MUTED" "$C_RESET"
    printf 'not from /etc/security/limits.d — set "default-ulimits" in\n'
    printf '/etc/docker/daemon.json if a node still reports a low nofile.\n'
    printf '%sA restart briefly disconnects the users served by that node.%s\n' "$C_WARN" "$C_RESET"
  fi

  if ((ST_OPT_BATCH)); then
    if [[ -n $containers ]]; then
      printf '%sNote:%s restart these containers so they pick up the new limits:\n  %s\n' \
        "$C_WARN" "$C_RESET" "$(awk '{printf "%s ", $2}' <<<"$containers")"
    fi
    return 0
  fi

  # The list is read through FD 3 on purpose: with the list on stdin, the
  # `read` inside ui_confirm would consume it instead of the user's answer —
  # and bash hides the prompt entirely when stdin is not a terminal.
  local engine_name name
  while IFS=$'\t' read -r engine_name name <&3; do
    [[ -n $name ]] || continue
    if ui_confirm "Restart ${engine_name} container '${name}' now so it picks up the new limits?"; then
      if "$engine_name" restart "$name" >/dev/null 2>>"$ST_LOG_FILE"; then
        printf '%sRestarted:%s %s\n' "$C_OK" "$C_RESET" "$name"
      else
        log_warn "Could not restart ${name}."
      fi
    fi
  done 3<<<"$containers"

  local svc
  for svc in xray x-ui sing-box hysteria-server; do
    if has_cmd systemctl && systemctl is-active --quiet "$svc" 2>/dev/null; then
      if ui_confirm "Restart service '${svc}' now so it picks up the new limits?"; then
        if systemctl restart "$svc" 2>>"$ST_LOG_FILE"; then
          printf '%sRestarted:%s %s\n' "$C_OK" "$C_RESET" "$svc"
        else
          log_warn "Could not restart ${svc}."
        fi
      fi
    fi
  done
  return 0
}

quick_optimize() {
  ui_logo
  ui_title "Quick Optimize"
  detect_stack
  profile_resolve_auto
  tier_compute

  printf 'The base layer always optimizes the whole server; the detected profile\n'
  printf 'only adds specialised tuning on top of it.\n'
  ui_hr
  _optimize_show_plan
  ui_hr

  local with_dns=0
  if dns_select_menu; then
    with_dns=1
  fi

  printf '\n'
  if ! ui_confirm "Apply the plan above?"; then
    ui_pause
    return 0
  fi
  _optimize_run "$with_dns" 1 1 1 1
  ui_pause
}

# _apply_cli_profile_tier — resolve profile/tier honouring --profile/--tier
# overrides; invalid values die with a clear message. Shared by auto+dry-run.
_apply_cli_profile_tier() {
  if [[ -n $ST_AUTO_PROFILE ]]; then
    case "$ST_AUTO_PROFILE" in
      general | vpn-node | wireguard | panel | full)
        ST_PROFILE="$ST_AUTO_PROFILE"
        ST_PROFILE_SOURCE='cli'
        ;;
      *) die "Invalid --profile '${ST_AUTO_PROFILE}' (general|vpn-node|wireguard|panel|full)." ;;
    esac
  else
    profile_resolve_auto
  fi

  if [[ -n $ST_AUTO_USERS && ! $ST_AUTO_USERS =~ ^[0-9]+$ ]]; then
    die "Invalid --users '${ST_AUTO_USERS}' (expected a number)."
  fi

  tier_compute
  if [[ -n $ST_AUTO_TIER ]]; then
    case "$ST_AUTO_TIER" in
      S | M | L | XL)
        tier_set "$ST_AUTO_TIER"
        capacity_apply_users # a manual tier must not silently drop the users model
        ;;
      *) die "Invalid --tier '${ST_AUTO_TIER}' (S|M|L|XL)." ;;
    esac
  fi
}

# auto_optimize — the non-interactive flow behind --auto. No prompts: DNS is
# only touched when --dns was given.
auto_optimize() {
  detect_stack
  _apply_cli_profile_tier

  local with_dns=0
  if [[ -n $ST_AUTO_DNS ]]; then
    dns_resolve_cli "$ST_AUTO_DNS" ||
      die "Invalid --dns '${ST_AUTO_DNS}' (provider name or ip1,ip2)."
    with_dns=1
  fi

  ui_title "Auto Optimize (non-interactive)"
  _optimize_show_plan
  _optimize_run "$with_dns" "$ST_AUTO_SWAP" "$ST_AUTO_LIMITS" "$ST_AUTO_EXTRAS" "$ST_AUTO_PERF"
}

# dry_run_optimize — --dry-run: show the plan and the exact sysctl diff,
# apply absolutely nothing.
dry_run_optimize() {
  detect_stack
  _apply_cli_profile_tier
  ui_title "Dry Run — nothing will be applied"
  _optimize_show_plan
  ui_hr
  sysctl_dry_run
  printf '\nA real run would also cover: CPU/NIC performance (RPS, governor, THP),\n'
  printf 'nofile limits, journald cap & NTP, swap%s.\n' \
    "$([[ -n $ST_AUTO_DNS ]] && printf ', DNS')"
}

custom_optimize() {
  ui_logo
  ui_title "Custom Optimize"
  detect_stack
  profile_resolve_auto
  local suggested="$ST_PROFILE"

  printf '%s[Workload profile]%s suggested: %s (%s)\n' \
    "$C_TITLE" "$C_RESET" "$suggested" "$ST_PROFILE_SOURCE"
  ui_menu_item 1 "general" "complete general-purpose tuning"
  ui_menu_item 2 "vpn-node" "Xray node (marzban-node / pg-node / x-ui)"
  ui_menu_item 3 "wireguard" "WireGuard host"
  ui_menu_item 4 "panel" "Marzban/Pasarguard panel host"
  ui_menu_item 5 "full" "everything with best-practice defaults"
  local choice
  read -rp "Select [Enter=suggested]: " choice || return 0
  case "${choice:-}" in
    1) ST_PROFILE='general' ;;
    2) ST_PROFILE='vpn-node' ;;
    3) ST_PROFILE='wireguard' ;;
    4) ST_PROFILE='panel' ;;
    5) ST_PROFILE='full' ;;
    *) ST_PROFILE="$suggested" ;;
  esac
  ST_PROFILE_SOURCE='manual'

  tier_compute
  local tier_choice
  read -rp "Capacity tier — auto picked ${ST_TIER} (up to ${ST_TIER_USERS} users). Override [S/M/L/XL, Enter=keep]: " tier_choice || tier_choice=''
  case "${tier_choice^^}" in
    S | M | L | XL)
      tier_set "${tier_choice^^}"
      config_set capacity_tier "${tier_choice^^}"
      ;;
  esac

  local users_in
  read -rp "Expected concurrent users [Enter=size by RAM, 0=reset saved value]: " users_in || users_in=''
  if [[ $users_in =~ ^[0-9]+$ ]]; then
    config_set expected_users "$users_in"
  fi
  capacity_apply_users

  ui_hr
  _optimize_show_plan
  ui_hr

  if ! ui_confirm_yes "Apply sysctl kernel tuning? (the core step)"; then
    printf 'Nothing to do without the sysctl step.\n'
    ui_pause
    return 0
  fi
  local with_swap=0 with_limits=0 with_extras=0 with_perf=0 with_dns=0
  ui_confirm_yes "Raise file-descriptor limits?" && with_limits=1
  ui_confirm_yes "Cap journald disk usage and enable NTP?" && with_extras=1
  ui_confirm_yes "Tune CPU/NIC data path (RPS, governor, THP)?" && with_perf=1
  ui_confirm_yes "Create a swap file if none exists?" && with_swap=1
  if dns_select_menu; then
    with_dns=1
  fi

  printf '\n'
  if ! ui_confirm "Apply now?"; then
    ui_pause
    return 0
  fi
  _optimize_run "$with_dns" "$with_swap" "$with_limits" "$with_extras" "$with_perf"
  ui_pause
}

# ------------------------- src/modules/doctor.sh -------------------------
# ============================================================================
# modules/doctor.sh — health check and drift detection (`--verify`).
#
# The verify contract every module follows:
#   0  applied and in effect
#   2  not configured by ServerTools (nothing to check)
#   3  configured but the live system disagrees — drift
#
# A kernel upgrade, a panel installer or a hand edit can undo tuning without
# telling anyone; this is where that becomes visible.
# ============================================================================

# Registry: "label|verify function|repair hint"
readonly -a ST_DOCTOR_CHECKS=(
  'Kernel tuning (sysctl)|sysctl_verify|re-run Quick Optimize'
  'CPU/NIC performance|perf_verify|re-run Quick Optimize'
  'DNS servers|dns_verify|Quick Optimize, then pick the provider again'
  'File limits (nofile)|limits_verify|re-run Quick Optimize'
  'Swap|swap_verify|Custom Optimize, enable the swap step'
  'SSH hardening|ssh_verify|Security menu, option 3'
  'MSS clamping|mss_verify|Network tools, option 5'
  'Conntrack NOTRACK|notrack_verify|Network tools, option n'
)

ST_DOCTOR_DRIFT=0
ST_DOCTOR_OK=0
ST_DOCTOR_NA=0

# _doctor_run_check LABEL FN HINT — one row of the report.
_doctor_run_check() {
  local label="$1" fn="$2" hint="$3" rc=0
  declare -F "$fn" >/dev/null 2>&1 || return 0
  "$fn" || rc=$?
  case "$rc" in
    0)
      ST_DOCTOR_OK=$((ST_DOCTOR_OK + 1))
      printf '  %s%-26s%s %sOK%s\n' "$C_KEY" "$label" "$C_RESET" "$C_OK" "$C_RESET"
      ;;
    2)
      ST_DOCTOR_NA=$((ST_DOCTOR_NA + 1))
      printf '  %s%-26s%s %snot configured%s\n' "$C_KEY" "$label" "$C_RESET" "$C_MUTED" "$C_RESET"
      ;;
    *)
      ST_DOCTOR_DRIFT=$((ST_DOCTOR_DRIFT + 1))
      printf '  %s%-26s%s %sDRIFT%s — %s\n' "$C_KEY" "$label" "$C_RESET" "$C_WARN" "$C_RESET" "$hint"
      ;;
  esac
}

# _doctor_json — machine-readable result for fleet automation.
_doctor_json() {
  local entry label fn hint rc first=1
  printf '{"version":"%s","host":"%s","checks":[' \
    "$ST_VERSION" "$(hostname 2>/dev/null || printf 'unknown')"
  for entry in "${ST_DOCTOR_CHECKS[@]}"; do
    IFS='|' read -r label fn hint <<<"$entry"
    declare -F "$fn" >/dev/null 2>&1 || continue
    rc=0
    "$fn" || rc=$?
    ((first)) || printf ','
    first=0
    case "$rc" in
      0) printf '{"check":"%s","status":"ok"}' "$label" ;;
      2) printf '{"check":"%s","status":"not_configured"}' "$label" ;;
      *) printf '{"check":"%s","status":"drift","hint":"%s"}' "$label" "$hint" ;;
    esac
    case "$rc" in
      0 | 2) : ;;
      *) ST_DOCTOR_DRIFT=$((ST_DOCTOR_DRIFT + 1)) ;;
    esac
  done
  printf '],"drift":%d,"profile":"%s","tier":"%s"}\n' \
    "$ST_DOCTOR_DRIFT" "$(config_get last_profile none)" "$(config_get last_tier -)"
}

# doctor_run — the whole report. Returns 0 when healthy, 3 on drift.
doctor_run() {
  ST_DOCTOR_DRIFT=0
  ST_DOCTOR_OK=0
  ST_DOCTOR_NA=0

  if ((ST_OPT_JSON)); then
    _doctor_json
    ((ST_DOCTOR_DRIFT > 0)) && return 3
    return 0
  fi

  ui_logo
  ui_title "Doctor — is everything still in effect?"
  ui_section "Checks"
  local entry label fn hint
  for entry in "${ST_DOCTOR_CHECKS[@]}"; do
    IFS='|' read -r label fn hint <<<"$entry"
    _doctor_run_check "$label" "$fn" "$hint"
  done
  ui_hr

  # Listening ports that appeared after the last apply are a silent hazard:
  # an outgoing connection can steal a port a node still needs.
  local unreserved
  unreserved="$(_doctor_unreserved_ports)"
  if [[ -n $unreserved ]]; then
    ST_DOCTOR_DRIFT=$((ST_DOCTOR_DRIFT + 1))
    printf '  %s%-26s%s %sDRIFT%s — %s not reserved; re-run Quick Optimize\n' \
      "$C_KEY" "Reserved service ports" "$C_RESET" "$C_WARN" "$C_RESET" "$unreserved"
    ui_hr
  fi

  ui_section "Effect since the last baseline"
  snapshot_report || printf '  (no baseline yet — it is taken on the next optimize run)\n'
  ui_hr

  if ((ST_DOCTOR_DRIFT > 0)); then
    printf '%s%d check(s) drifted%s · %d OK · %d not configured\n' \
      "$C_WARN" "$ST_DOCTOR_DRIFT" "$C_RESET" "$ST_DOCTOR_OK" "$ST_DOCTOR_NA"
    printf 'Run "st --dry-run" to see exactly which kernel keys differ.\n'
    return 3
  fi
  printf '%sEverything ServerTools configured is still in effect.%s (%d OK, %d not configured)\n' \
    "$C_OK" "$C_RESET" "$ST_DOCTOR_OK" "$ST_DOCTOR_NA"
  return 0
}

# _doctor_unreserved_ports — listening ports inside the ephemeral range that
# the current sysctl file does not reserve (typically inbounds added later).
_doctor_unreserved_ports() {
  [[ -f $ST_SYSCTL_FILE ]] || return 0
  local reserved port missing=''
  reserved="$(awk -F'= *' '/ip_local_reserved_ports/ {print $2; exit}' "$ST_SYSCTL_FILE")" || reserved=''
  [[ -n $reserved ]] || return 0

  # Same source as the apply step, so a service that started later shows up
  # while transient proxy sockets do not raise a false alarm.
  while IFS= read -r port; do
    [[ $port =~ ^[0-9]+$ ]] || continue
    _port_in_reserved_list "$port" "$reserved" || missing+="${port} "
  done < <(listening_service_ports)

  printf '%s' "${missing% }"
}

# _port_in_reserved_list PORT LIST — LIST holds numbers and "a-b" ranges.
_port_in_reserved_list() {
  local port="$1" item low high
  for item in ${2//,/ }; do
    if [[ $item == *-* ]]; then
      low="${item%%-*}"
      high="${item##*-}"
      ((port >= low && port <= high)) && return 0
    elif [[ $item == "$port" ]]; then
      return 0
    fi
  done
  return 1
}

# ------------------------- src/menu.sh -------------------------
# ============================================================================
# menu.sh — interactive main menu and sub-screens.
# The dashboard must render instantly: everything network-bound is cached
# (public IP is fetched at most once per process, in utils.sh).
# ============================================================================

menu_dashboard() {
  ui_logo

  # Optimized state is a first-class signal: a returning user should see at a
  # glance whether this host has been tuned, without reading a report.
  local prof tier status
  prof="$(config_get last_profile '')"
  tier="$(config_get last_tier '-')"
  if [[ -n $prof ]]; then
    status="$(ui_badge ok) optimized  ${C_MUTED}(profile ${prof} · tier ${tier})${C_RESET}"
  else
    status="$(ui_badge idle) not optimized yet  ${C_MUTED}(start with Quick Optimize)${C_RESET}"
  fi

  ui_section "System"
  ui_kv "Host" "$(hostname 2>/dev/null || printf 'unknown')"
  ui_kv "OS" "$(os_pretty_name)"
  ui_kv "Kernel" "$(kernel_release)"
  ui_kv "Resources" "$(cpu_cores) vCPU · $(mem_total_mb) MB RAM · up $(uptime_pretty)"
  printf '\n'
  ui_section "Network & workload"
  ui_kv "Public IPv4" "$(net_public_ip4)"
  ui_kv "TCP stack" "cc=$(sysctl_get net.ipv4.tcp_congestion_control) · qdisc=$(sysctl_get net.core.default_qdisc)"
  ui_kv "Detected" "$(detect_summary)"
  ui_kv "Status" "$status"
  ui_hr
}

menu_rollback() {
  ui_logo
  ui_title "Rollback"
  local run choice
  run="$(manifest_latest_run)"
  if [[ -z $run ]]; then
    printf 'No recorded changes yet — nothing to roll back.\n'
    ui_pause
    return 0
  fi
  printf 'Latest recorded run: %s%s%s · %s change(s) recorded in total\n' \
    "$C_ACCENT" "$run" "$C_RESET" "$(manifest_entry_count)"
  ui_hr
  ui_menu_item 1 "Undo the last run" "restore files that run changed, remove what it created"
  ui_menu_item 2 "Restore original state" "everything back to before ServerTools ever ran"
  ui_menu_item 0 "Back"
  ui_hr
  read -rp "Select: " choice || return 0
  case "${choice:-}" in
    1) ui_confirm "Revert all changes from run ${run}?" && rollback_latest ;;
    2)
      printf '%sThis undoes every ServerTools change on this host.%s\n' "$C_WARN" "$C_RESET"
      ui_confirm "Restore the original (factory) state?" && rollback_original
      ;;
    *) return 0 ;;
  esac
  ui_pause
}

menu_settings() {
  local choice
  while true; do
    ui_logo
    ui_title "Settings & Maintenance"
    ui_kv "Version" "$ST_VERSION"
    ui_kv "Config file" "$ST_CONFIG_FILE"
    ui_kv "Log file" "$ST_LOG_FILE"
    ui_kv "Backups" "$ST_BACKUP_DIR"
    ui_kv "Recorded changes" "$(manifest_entry_count)"
    ui_kv "Saved profile" "$(config_get last_profile 'none yet') / tier $(config_get last_tier '-')"
    ui_hr
    ui_menu_item 1 "Install 'st' command" "run 'st' instead of the long one-liner"
    ui_menu_item 2 "Check for updates" "self-update from the latest release"
    ui_menu_item 0 "Back"
    ui_hr
    read -rp "Select: " choice || return 0
    case "${choice:-}" in
      1)
        st_self_install || log_warn "Install did not complete."
        ui_pause
        ;;
      2)
        st_self_update || log_warn "Update did not complete."
        ui_pause
        ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

main_menu() {
  detect_stack
  local choice
  while true; do
    menu_dashboard
    ui_menu_group "Optimize"
    ui_menu_item 1 "Quick Optimize" "full auto-tune, recommended — safe to re-run"
    ui_menu_item 2 "Custom Optimize" "pick profile and modules manually"
    ui_menu_group "Inspect"
    ui_menu_item 3 "System Status" "full live report"
    ui_menu_item 4 "Doctor" "drift check — is everything still in effect?"
    ui_menu_group "Recover"
    ui_menu_item 5 "Rollback" "undo changes — restore to before ServerTools"
    ui_menu_group "Secure"
    ui_menu_item 6 "Security" "UFW · fail2ban · SSH · anti-abuse (optional)"
    ui_menu_group "Tools"
    ui_menu_item 7 "Network & VPN tools" "ping · speed · MSS · NOTRACK · live view"
    ui_menu_item 8 "Node & Docker" "config backup · installers · container limits"
    ui_menu_group "Maintain"
    ui_menu_item 9 "Settings" "install 'st' command · self-update · paths"
    ui_menu_item 0 "Exit"
    ui_hr
    ui_hint "New here? Choose 1 — it detects your workload and tunes everything safely."
    # EOF (e.g. closed stdin) simply exits the menu.
    read -rp "$(_ui_glyph '❯' '>') Select an option: " choice || {
      printf '\n'
      return 0
    }
    case "${choice:-}" in
      1) quick_optimize ;;
      2) custom_optimize ;;
      3) show_status ;;
      4)
        doctor_run || true # drift is reported on screen, not an error here
        ui_pause
        ;;
      5) menu_rollback ;;
      6) security_menu ;;
      7) tools_menu ;;
      8) node_menu ;;
      9) menu_settings ;;
      0) return 0 ;;
      *)
        printf '%sInvalid choice.%s\n' "$C_ERR" "$C_RESET"
        sleep 1
        ;;
    esac
  done
}

# ------------------------- src/99-main.sh -------------------------
# ============================================================================
# 99-main.sh — CLI argument parsing and the program entrypoint.
# This file MUST be last in the build order (see build.sh SOURCES).
# ============================================================================

usage() {
  cat <<EOF
${ST_NAME} v${ST_VERSION} — Linux server optimization toolkit
${ST_REPO_URL}

Usage: server-tools.sh [OPTIONS]   (installed: st [OPTIONS])

Actions (no action starts the interactive menu):
  --status              Print the full system status report and exit
  --auto                Non-interactive optimize: base layer + detected profile
  --dry-run             Show the plan and exact sysctl diff, apply NOTHING
  --verify              Check whether everything applied is still in effect
  --report              Print + save a plain-text support report
  --rollback            Revert the latest recorded run and exit
  --rollback-original   Restore the state from before ServerTools ever ran
  --install             Install as the 'st' command (/usr/local/bin/st)
  --update              Self-update from the latest GitHub release

Options for --auto and --dry-run:
  --profile NAME        general | vpn-node | wireguard | panel | full
  --tier T              Capacity tier: S | M | L | XL (default: by RAM)
  --users N             Expected concurrent users — sizes conntrack from the
                        real user count instead of RAM (with a RAM warning)
  --dns VALUE           Provider (cloudflare|google|quad9|opendns|shecan|
                        electro|begzar) or custom "primary,secondary"
  --no-swap             Skip the swap step
  --no-limits           Skip the nofile limits step
  --no-extras           Skip the journald/NTP step
  --no-perf             Skip the CPU/NIC performance step (RPS, governor, THP)

General options:
  --json                Machine-readable output (--verify)
  --no-color            Disable colored output (NO_COLOR env also honoured)
  --debug               Verbose logging to console and log file
  -v, --version         Print version and exit
  -h, --help            Show this help

Exit codes:
  0  everything succeeded    1  at least one step failed
  2  usage error             3  applied, but with warnings / drift found

Example (fleet provisioning):
  st --auto --profile vpn-node --users 10000 --dns cloudflare
  st --verify --json    # nightly drift check from your own automation
EOF
}

_need_value() { # _need_value OPTION VALUE
  if [[ -z ${2:-} ]]; then
    printf 'Missing value for %s\n' "$1" >&2
    exit 2
  fi
}

main() {
  local action="menu" tuning_opts=''
  while (($# > 0)); do
    case "$1" in
      -v | --version)
        printf '%s %s\n' "$ST_NAME" "$ST_VERSION"
        return 0
        ;;
      -h | --help)
        usage
        return 0
        ;;
      --status) action="status" ;;
      --rollback) action="rollback" ;;
      --rollback-original) action="rollback_original" ;;
      --auto) action="auto" ;;
      --dry-run) action="dryrun" ;;
      --verify | --doctor) action="verify" ;;
      --report) action="report" ;;
      --install) action="install" ;;
      --update) action="update" ;;
      --profile)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_PROFILE="$1"
        tuning_opts='yes'
        ;;
      --tier)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_TIER="${1^^}"
        tuning_opts='yes'
        ;;
      --users)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_USERS="$1"
        tuning_opts='yes'
        ;;
      --dns)
        _need_value "$1" "${2:-}"
        shift
        ST_AUTO_DNS="$1"
        tuning_opts='yes'
        ;;
      --no-swap)
        ST_AUTO_SWAP=0
        tuning_opts='yes'
        ;;
      --no-limits)
        ST_AUTO_LIMITS=0
        tuning_opts='yes'
        ;;
      --no-extras)
        ST_AUTO_EXTRAS=0
        tuning_opts='yes'
        ;;
      --no-perf)
        ST_AUTO_PERF=0
        tuning_opts='yes'
        ;;
      --json) ST_OPT_JSON=1 ;;
      --no-color) ST_OPT_NO_COLOR=1 ;;
      --debug) ST_OPT_DEBUG=1 ;;
      *)
        printf 'Unknown option: %s\n\n' "$1" >&2
        usage >&2
        exit 2
        ;;
    esac
    shift
  done

  # Tuning options only mean something for a non-interactive run; silently
  # ignoring them would hide a typo in a provisioning script.
  if [[ -n $tuning_opts && $action != auto && $action != dryrun ]]; then
    printf 'Options like --profile/--tier/--users/--dns require --auto or --dry-run.\n' >&2
    exit 2
  fi

  ui_detect_terminal
  require_root
  log_init
  state_init
  config_load
  log_info "${ST_NAME} v${ST_VERSION} started (run ${ST_RUN_ID}, action=${action})"

  case "$action" in
    status)
      ST_OPT_BATCH=1
      detect_stack
      show_status
      ;;
    rollback)
      ST_OPT_BATCH=1
      rollback_latest
      ;;
    rollback_original)
      ST_OPT_BATCH=1
      rollback_original
      ;;
    auto)
      ST_OPT_BATCH=1
      auto_optimize
      ;;
    dryrun)
      ST_OPT_BATCH=1
      ST_DRY_RUN=1
      dry_run_optimize
      ;;
    verify)
      ST_OPT_BATCH=1
      detect_stack
      doctor_run || st_escalate_exit $?
      ;;
    report)
      ST_OPT_BATCH=1
      detect_stack
      tools_report
      ;;
    install)
      ST_OPT_BATCH=1
      st_self_install || st_escalate_exit 1
      ;;
    update)
      ST_OPT_BATCH=1
      st_self_update || st_escalate_exit 1
      ;;
    menu)
      main_menu
      ;;
  esac

  # The work is done; from here we only report and return the computed status.
  # ST_EXIT_CODE deliberately carries 1 (a step failed) or 3 (warning/drift),
  # so the ERR trap must be cleared first — otherwise this very `return` looks
  # to it like an unhandled failure and prints a spurious ERROR on every run
  # that ends in a warning (which is almost every real run).
  trap - ERR
  log_info "${ST_NAME} finished (run ${ST_RUN_ID}, exit=${ST_EXIT_CODE})"
  return "$ST_EXIT_CODE"
}

main "$@"
